actions.script:
import org.moqui.resource.ResourceReference
import groovy.util.Node

detectedEntities = []
ec.logger.info("🔍 [AgiEntityServices] Introspecting artifactUri: ${artifactUri}")

if (!artifactUri) {
    ec.logger.warn("⚠️ [AgiEntityServices] artifactUri is empty")
    return
}

ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (!rr || !rr.exists) {
    ec.logger.warn("⚠️ [AgiEntityServices] Resource does not exist at location: ${artifactUri}")
    return
}

String screenText = rr.getText()
Node screenNode = null
try {
    groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
    parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
    screenNode = parser.parseText(screenText)
} catch (Exception e) {
    ec.logger.error("❌ [AgiEntityServices] Failed to parse XML text for ${artifactUri}: ${e.message}")
    return
}

Set<String> entityNames = new LinkedHashSet<>()

screenNode.depthFirst().each { Node n ->
    String nodeName = n.name()?.toString()
    Map attrs = n.attributes() ?: [:]

    if (nodeName == 'service-call') {
        String sName = attrs.get('name') ?: ''
        if (sName.contains('#')) {
            String possibleEntity = sName.substring(sName.indexOf('#') + 1)
            ec.logger.info("👉 [AgiEntityServices] Found service-call target: ${possibleEntity}")
            entityNames.add(possibleEntity)
        }
    } else if (nodeName in ['entity-find-one', 'entity-find', 'entity-auto']) {
        String ent = attrs.get('entity-name') ?: ''
        if (ent) {
            ec.logger.info("👉 [AgiEntityServices] Found entity-find/auto target: ${ent}")
            entityNames.add(ent)
        }
    }
}

// Domain fallback for Mantle UDM base entity grounding
if (artifactUri.contains('Patient') || entityNames.any { it.toLowerCase().contains('patient') }) {
    entityNames.add('nursinghome.patient.Patient')
    entityNames.add('mantle.party.Person')
    entityNames.add('mantle.party.Party')
}

ec.logger.info("📋 [AgiEntityServices] Resolved candidate entities: ${entityNames}")

def findEntityDef = { String name ->
    if (!name) return null
    try {
        if (ec.entity.isEntityDefined(name)) return ec.entity.getEntityDefinition(name)
        String shortName = name.contains('.') ? name.split('\\.').last() : name
        if (ec.entity.isEntityDefined(shortName)) return ec.entity.getEntityDefinition(shortName)
    } catch (Exception ignored) { }
    return null
}

entityNames.each { String entName ->
    try {
        def ed = findEntityDef(entName)
        if (ed != null) {
            String resolvedName = ed.getFullEntityName()
            Map fieldsMap = [:]
            ed.getFieldNames(true, true).each { String fName ->
                def fi = ed.getFieldInfo(fName)
                if (fi != null) {
                    fieldsMap.put(fName, [
                        type     : fi.type ?: 'text-medium',
                        isPk     : fi.isPk,
                        encrypt  : fi.encrypt ?: false
                    ])
                }
            }

            List rels = []
            ed.getRelationshipsInfo(false).each { rel ->
                rels.add([
                    relatedEntity: rel.relatedEntityName,
                    type         : rel.type,
                    title        : rel.title ?: ''
                ])
            }

            detectedEntities.add([
                entityName   : resolvedName,
                isPrimary    : detectedEntities.isEmpty(),
                enabled      : true,
                fields       : fieldsMap,
                relationships: rels
            ])
            ec.logger.info("✅ [AgiEntityServices] Ground entity: ${resolvedName} (${fieldsMap.size()} fields)")
        } else if (entName == 'nursinghome.patient.Patient') {
            detectedEntities.add([
                entityName   : 'nursinghome.patient.Patient (Target Entity)',
                isPrimary    : true,
                enabled      : true,
                fields       : [
                    patientId       : [type: 'id', isPk: true, encrypt: false],
                    partyId         : [type: 'id', isPk: false, encrypt: false],
                    medicalRecordNum: [type: 'text-short', isPk: false, encrypt: true],
                    admissionDate   : [type: 'date-time', isPk: false, encrypt: false]
                ],
                relationships: [
                    [relatedEntity: 'mantle.party.Person', type: 'one', title: 'PersonRecord']
                ]
            ])
        }
    } catch (Exception e) {
        ec.logger.warn("⚠️ [AgiEntityServices] Error resolving entity metadata for ${entName}: ${e.message}")
    }
}

ec.logger.info("🎯 [AgiEntityServices] Total detected entities output: ${detectedEntities.size()}")

import org.moqui.resource.ResourceReference
import groovy.util.Node

if (artifactUri) {
    ResourceReference rr = ec.resource.getLocationReference(artifactUri)
    if (rr && rr.exists) {
        rawXmlContent = rr.getText()
        groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
        parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
        Node rootNode = parser.parseText(rawXmlContent)

        def parseNodeToAst
        parseNodeToAst = { Node n ->
            Map nodeMap = [
                name      : n.name()?.toString(),
                attributes: n.attributes() ?: [:],
                children  : []
            ]
            n.children().each { child ->
                if (child instanceof Node) nodeMap.children.add(parseNodeToAst(child))
            }
            return nodeMap
        }
        entityAst = parseNodeToAst(rootNode)
        return
    }
}

String lookupName = entityName ?: (artifactUri ? artifactUri.split('/').last().replace('.entity.xml', '').replace('.xml', '') : null)
if (lookupName && ec.entity.isEntityDefined(lookupName)) {
    def ed = ec.entity.getEntityDefinition(lookupName)
    List fields = []
    ed.getFieldNames(true, true).each { String fName ->
        def fi = ed.getFieldInfo(fName)
        if (fi != null) {
            fields.add([
                name      : 'field',
                attributes: [
                    name    : fName,
                    type    : fi.type ?: 'text-medium',
                    isPk    : fi.isPk ? 'true' : 'false',
                    encrypt : fi.encrypt ? 'true' : 'false'
                ]
            ])
        }
    }

    List relationships = []
    ed.getRelationshipsInfo(false).each { rel ->
        relationships.add([
            name      : 'relationship',
            attributes: [
                type          : rel.type ?: 'one',
                'related'     : rel.relatedEntityName,
                title         : rel.title ?: ''
            ]
        ])
    }

    entityAst = [
        name      : 'entities',
        attributes: [
            'xmlns:xsi': 'http://www.w3.org/2001/XMLSchema-instance',
            'xsi:noNamespaceSchemaLocation': 'http://moqui.org/xsd/moqui-entity-3.xsd'
        ],
        children  : [
            [
                name      : 'entity',
                attributes: [
                    'entity-name'      : ed.getEntityName(),
                    'package'          : ed.groupName ?: 'nursinghome',
                    'enable-audit-log' : 'true'
                ],
                children  : fields + relationships
            ]
        ]
    ]
}

import org.moqui.resource.ResourceReference
import groovy.xml.MarkupBuilder

String finalXml = rawXmlContent
if (!finalXml && entityAst) {
    StringWriter writer = new StringWriter()
    MarkupBuilder xml = new MarkupBuilder(writer)

    def renderAstNode
    renderAstNode = { Map node, MarkupBuilder builder ->
        String tag = node.name ?: 'entity'
        Map attrs = node.attributes ?: [:]
        List children = node.children ?: []

        if (children.isEmpty()) {
            builder."${tag}"(attrs)
        } else {
            builder."${tag}"(attrs) {
                children.each { child ->
                    if (child instanceof Map) renderAstNode(child, builder)
                }
            }
        }
    }

    renderAstNode(entityAst, xml)
    finalXml = '<?xml version="1.0" encoding="UTF-8"?>\n' + writer.toString()
}

if (finalXml && artifactUri) {
    ResourceReference rr = ec.resource.getLocationReference(artifactUri)
    rr.putText(finalXml)
    status = "SUCCESS"
    message = "Entity definition successfully saved to disk."
} else {
    status = "ERROR"
    message = "No XML or AST provided."
}

if (!ec.entity.isEntityDefined(entityName)) {
    status = "NOT_FOUND"
    records = []
    totalCount = 0
    return
}

def ef = ec.entity.find(entityName).limit(limit)
records = ef.list()?.collect { it.getMap() } ?: []
totalCount = ef.count()
status = "SUCCESS"

import org.moqui.resource.ResourceReference
import groovy.xml.XmlUtil
import groovy.xml.XmlParser

String comp = targetComponent
String entityFileLocation = "component://${comp}/entity/${comp.capitalize()}Entities.xml"
ResourceReference entityRef = ec.resource.getLocationReference(entityFileLocation)

// Prepare or load existing entities XML
groovy.util.Node rootEntities
if (entityRef != null && entityRef.exists) {
    rootEntities = new XmlParser(false, false).parseText(entityRef.getText())
} else {
    rootEntities = new groovy.util.Node(null, 'entities', [
        'xmlns:xsi': 'http://www.w3.org/2001/XMLSchema-instance',
        'xsi:noNamespaceSchemaLocation': 'http://moqui.org/xsd/entity-definition-3.xsd'
    ])
}

List generated = []

missingEntities.each { String fullEntityName ->
    // Check if already defined in the file
    String simpleName = fullEntityName.contains('.') ? fullEntityName.substring(fullEntityName.lastIndexOf('.') + 1) : fullEntityName
    String pkgName = fullEntityName.contains('.') ? fullEntityName.substring(0, fullEntityName.lastIndexOf('.')) : comp

    boolean existsInDoc = rootEntities.children().any { ch -> ch.name() == 'entity' && ch.attribute('entity-name') == simpleName }
    if (existsInDoc) return

    boolean isSensitive = simpleName.toLowerCase().contains("medical") || 
                          simpleName.toLowerCase().contains("patient") || 
                          simpleName.toLowerCase().contains("clinical") ||
                          simpleName.toLowerCase().contains("safety")

    Map entityAttrs = [
        'entity-name': simpleName,
        'package': pkgName
    ]
    if (isSensitive) {
        entityAttrs['enable-audit-log'] = 'true'
    }

    groovy.util.Node newEntity = rootEntities.appendNode('entity', entityAttrs)

    // Standard Primary Key
    String pkField = simpleName.uncapitalize() + "Id"
    newEntity.appendNode('field', ['name': pkField, 'type': 'id', 'is-pk': 'true'])

    // Standard Scope/Foreign Keys
    newEntity.appendNode('field', ['name': 'facilityId', 'type': 'id'])
    newEntity.appendNode('field', ['name': 'statusId', 'type': 'id'])

    // Domain-specific heuristic fields based on name
    if (simpleName.contains("Log")) {
        newEntity.appendNode('field', ['name': 'logDate', 'type': 'date-time'])
        newEntity.appendNode('field', ['name': 'description', 'type': 'text-medium'])
    } else if (simpleName.contains("Profile")) {
        newEntity.appendNode('field', ['name': 'partyId', 'type': 'id'])
        newEntity.appendNode('field', ['name': 'medicalSummary', 'type': 'text-medium', 'encrypt': 'true'])
    }

    generated.add(fullEntityName)
}

// Write back updated entity XML
if (generated) {
    String serializedXml = XmlUtil.serialize(rootEntities)
    File physFile = new File("runtime/component/${comp}/entity/${comp.capitalize()}Entities.xml")
    physFile.getParentFile().mkdirs()
    physFile.text = serializedXml

    // Reload entity definitions into Moqui runtime
    ec.entity.entityFacade.loadEntityDefinitions(entityRef.getLocation())
    ec.logger.info("🌱 [scaffold#MissingEntities] Staged and registered entities: ${generated}")
}

context.entityXmlLocation = entityFileLocation
context.generatedEntities = generated
